"""Optional glossary forcing for Opus MT + ASR source corrections."""

from __future__ import annotations

import re
from typing import Any


def normalize_glossary(raw: Any) -> list[tuple[str, str]]:
    """
    Accept flexible client shapes:
      {"src"|"source"|"from", "tgt"|"target"|"to"|"zh"}
      ["src", "tgt"]
    Longer source phrases are applied first to avoid partial overlaps.
    """
    return [(s, t) for s, t, _stage in normalize_glossary_entries(raw)]


def normalize_glossary_entries(raw: Any) -> list[tuple[str, str, str]]:
    """
    Like normalize_glossary but keeps stage:

      stage "asr"  — replace misheard → correct on source cues (same language)
      stage "mt"   — protect/restore for machine translation (default)

    Entry shapes:
      {src, tgt, stage?}
      {wrong|misheard, correct|fix, stage: "asr"}
      [src, tgt]
    """
    if not raw:
        return []
    if not isinstance(raw, (list, tuple)):
        return []
    items: list[tuple[str, str, str]] = []
    for entry in raw:
        src = tgt = ""
        stage = "mt"
        if isinstance(entry, dict):
            stage_raw = str(
                entry.get("stage") or entry.get("role") or entry.get("scope") or ""
            ).strip().lower()
            if stage_raw in ("asr", "source", "correct", "fix"):
                stage = "asr"
            elif stage_raw in ("mt", "translate", "nmt"):
                stage = "mt"
            src = str(
                entry.get("src")
                or entry.get("source")
                or entry.get("from")
                or entry.get("term")
                or entry.get("wrong")
                or entry.get("misheard")
                or ""
            ).strip()
            tgt = str(
                entry.get("tgt")
                or entry.get("target")
                or entry.get("to")
                or entry.get("zh")
                or entry.get("translation")
                or entry.get("correct")
                or entry.get("fix")
                or ""
            ).strip()
            # Explicit ASR-only keys without stage
            if stage == "mt" and (
                entry.get("wrong")
                or entry.get("misheard")
                or entry.get("correct")
                or entry.get("fix")
            ):
                stage = "asr"
        elif isinstance(entry, (list, tuple)) and len(entry) >= 2:
            src = str(entry[0] or "").strip()
            tgt = str(entry[1] or "").strip()
            if len(entry) >= 3 and str(entry[2] or "").strip().lower() in (
                "asr",
                "source",
                "correct",
                "fix",
            ):
                stage = "asr"
        if src and tgt and src != tgt:
            items.append((src, tgt, stage))
    # Deduplicate by (stage, src); last wins; longest src first within stage
    by_key: dict[tuple[str, str], str] = {}
    for src, tgt, stage in items:
        by_key[(stage, src)] = tgt
    ordered = sorted(
        ((stage, src, tgt) for (stage, src), tgt in by_key.items()),
        key=lambda row: (0 if row[0] == "asr" else 1, -len(row[1]), row[1]),
    )
    return [(src, tgt, stage) for stage, src, tgt in ordered]


def split_glossary(raw: Any) -> tuple[list[tuple[str, str]], list[tuple[str, str]]]:
    """Return (asr_entries, mt_entries)."""
    asr: list[tuple[str, str]] = []
    mt: list[tuple[str, str]] = []
    for src, tgt, stage in normalize_glossary_entries(raw):
        if stage == "asr":
            asr.append((src, tgt))
        else:
            mt.append((src, tgt))
    return asr, mt


def _token(i: int) -> str:
    # ASCII placeholder survives Marian / SentencePiece better than CJK PUA.
    return f"__GLOSS{i}__"


def _is_latin_term(src: str) -> bool:
    return bool(src) and all(ord(ch) < 128 for ch in src) and bool(re.search(r"[A-Za-z]", src))


def _is_kana_heavy(text: str) -> bool:
    s = str(text or "")
    if not s:
        return False
    kana = sum(1 for ch in s if "\u3040" <= ch <= "\u30ff")
    return kana >= max(1, (len(s) + 1) // 2)


# Loanword / compound tails where a short mishear (esp. マイ) is NOT a person name.
_NAME_SKIP_AFTER: dict[str, tuple[str, ...]] = {
    "マイ": (
        "ク",
        "ペース",
        "ナー",
        "ホーム",
        "スコ",
        "グロ",
        "ケミ",
        "ラス",
        "ンド",
        "ンデ",
        "ガスター",
        "クろ",
        "クロ",
        "ンドフル",
        "ブ",
        "ナ",
        "ナス",
        "チ",
    ),
    "マリ": ("ア", "オ", "ン", "ネ", "ッジ"),
    "ヒロ": ("イン", "シマ", "キ", "セ"),
}

# Compounds where the token is a *suffix* (トラマイ, オーマイ…) — not a person name.
_NAME_SKIP_BEFORE: dict[str, tuple[str, ...]] = {
    "マイ": ("トラ", "オー", "ゼン", "セミ", "ワン", "う", "ウ"),
    # うまい (delicious) must not become う舞
    "まい": ("う", "ウ"),
}

_HONORIFICS = ("ちゃん", "さん", "くん", "様", "君", "氏", "たん", "っち")
_NAME_FOLLOW_OK = (
    "です",
    "だよ",
    "だね",
    "だな",
    "なの",
    "って",
    "も",
    "の",
    "が",
    "を",
    "は",
    "と",
    "に",
    "へ",
    "や",
    "か",
    "ね",
    "よ",
    "わ",
    "？",
    "?",
    "。",
    "！",
    "!",
    "、",
    "…",
    "ー",
    "〜",
    "～",
    " ",
    "\u3000",
)
_NAME_PREFIX_OK = (
    "彼女の",
    "彼の",
    "僕の",
    "俺の",
    "私の",
    "あたしの",
    "うちの",
    "友達の",
    "なあ",
    "ねぇ",
    "ねえ",
    "おい",
    "ほら",
    "あの",
    "あのー",
    "あのー、",
    "はい",
    "よし",
    "じゃあ",
    "じゃあね",
    "ちょっと",
    "ねぇ、",
    "ねえ、",
    "おい、",
    "ほら、",
)


def _looks_like_ja_person_token(src: str) -> bool:
    """Short JA name-like token suitable for contextual ASR replace / Whisper bias."""
    s = str(src or "").strip()
    if not s or len(s) > 8:
        return False
    if _is_latin_term(s):
        return True
    # Prefer kana / short mixed names (マイ, あかり, 桃子, まひろ)
    if len(s) <= 5 and _is_kana_heavy(s):
        return True
    if 1 <= len(s) <= 5 and all(
        "\u4e00" <= ch <= "\u9fff" or "\u3040" <= ch <= "\u30ff" for ch in s
    ):
        return True
    return False


def expand_asr_name_entries(entries: list[tuple[str, str]]) -> list[tuple[str, str]]:
    """
    Expand short name mishears into longer safe patterns (longest-first later).

    Example: マイ→舞 also yields マイちゃん→舞ちゃん, 彼女のマイ→彼女の舞, …
    """
    if not entries:
        return []
    extras: list[tuple[str, str]] = []
    seen = {(s, t) for s, t in entries}
    for src, tgt in entries:
        if not _looks_like_ja_person_token(src):
            continue
        candidates = [
            (f"{src}{h}", f"{tgt}{h}") for h in _HONORIFICS
        ] + [
            (f"{p}{src}", f"{p}{tgt}") for p in _NAME_PREFIX_OK
        ] + [
            (f"{src}です", f"{tgt}です"),
            (f"{src}だよ", f"{tgt}だよ"),
            (f"{src}だね", f"{tgt}だね"),
            (f"{src}です。", f"{tgt}です。"),
            (f"{src}！", f"{tgt}！"),
            (f"{src}?", f"{tgt}?"),
            (f"{src}？", f"{tgt}？"),
            (f"{src}大丈夫", f"{tgt}大丈夫"),
            (f"{src}大丈夫?", f"{tgt}大丈夫?"),
            (f"{src}大丈夫？", f"{tgt}大丈夫？"),
            (f"{src}好き", f"{tgt}好き"),
            (f"{src}来て", f"{tgt}来て"),
        ]
        for a, b in candidates:
            if a != b and (a, b) not in seen:
                seen.add((a, b))
                extras.append((a, b))
    merged = list(entries) + extras
    merged.sort(key=lambda row: (-len(row[0]), row[0]))
    return merged


def _is_cjk_letter(ch: str) -> bool:
    if not ch:
        return False
    o = ord(ch)
    return (
        0x3040 <= o <= 0x30FF  # kana
        or 0x4E00 <= o <= 0x9FFF  # CJK
        or 0x3400 <= o <= 0x4DBF  # ext-A
        or ch.isalpha()
    )


def collect_ja_cast_names(
    glossary: Any = None,
    cast_names: Any = None,
    *,
    asr_only: bool = True,
) -> list[str]:
    """Ordered unique person-name orthographies from asrGlossary + castNames."""
    names: list[str] = []
    seen: set[str] = set()

    def _add(raw: str) -> None:
        name = str(raw or "").strip()
        if not name or name in seen:
            return
        if not _looks_like_ja_person_token(name) and len(name) > 6:
            return
        seen.add(name)
        names.append(name)

    if isinstance(cast_names, (list, tuple)):
        for item in cast_names:
            _add(str(item))
    if glossary:
        asr_entries, _mt = split_glossary(glossary)
        if asr_only and not asr_entries:
            asr_entries = normalize_glossary(glossary)
        for _wrong, correct in asr_entries:
            _add(correct)
    return names


def mt_name_lock_entries(names: list[str] | None) -> list[dict[str, str]]:
    """
    Identity MT glossary rows so kanji/kana cast names survive Opus (舞≠舞蹈).

    Longer names first via normalize_glossary ordering later.
    """
    out: list[dict[str, str]] = []
    for name in names or []:
        n = str(name or "").strip()
        if not n or len(n) > 8:
            continue
        if not any("\u4e00" <= ch <= "\u9fff" or "\u3040" <= ch <= "\u30ff" for ch in n):
            continue
        out.append({"src": n, "tgt": n, "stage": "mt"})
    return out


def names_for_whisper_bias(
    glossary: Any,
    *,
    asr_only: bool = True,
    cast_names: Any = None,
) -> tuple[str, str]:
    """
    Build (initial_prompt, hotwords) from ASR glossary + castNames.

    Prompt includes wrong→correct readings when available (舞（マイ）).
    """
    asr_entries, _mt = split_glossary(glossary)
    if asr_only and not asr_entries:
        asr_entries = normalize_glossary(glossary)

    labels: list[str] = []
    hot: list[str] = []
    seen: set[str] = set()

    def _push(label: str, *hot_forms: str) -> None:
        if label in seen:
            return
        seen.add(label)
        labels.append(label)
        for form in hot_forms:
            f = str(form or "").strip()
            if f and f not in hot:
                hot.append(f)

    if isinstance(cast_names, (list, tuple)):
        for item in cast_names:
            name = str(item or "").strip()
            if name:
                _push(name, name)

    for wrong, correct in asr_entries:
        name = str(correct or "").strip()
        if not name:
            continue
        if not _looks_like_ja_person_token(name) and len(name) > 6:
            continue
        w = str(wrong or "").strip()
        if w and w != name and _looks_like_ja_person_token(w):
            _push(f"{name}（{w}）", name, w)
        else:
            _push(name, name)

    if not labels:
        return "", ""
    prompt = "登場人物の名前は" + "、".join(labels) + "です。"
    return prompt, " ".join(hot)


def _replace_cjk_name_safe(text: str, src: str, replacement: str) -> str:
    """
    Replace short JA name tokens without breaking loanwords (マイク, マイペース, …).

    Longer / expanded patterns still use literal replace via caller order.
    """
    if not src or src not in text:
        return text
    skip_tails = _NAME_SKIP_AFTER.get(src, ())
    skip_heads = _NAME_SKIP_BEFORE.get(src, ())
    # Short kana-heavy tokens: require name-like context unless expanded pattern
    require_context = len(src) <= 3 and _is_kana_heavy(src)
    out: list[str] = []
    i = 0
    n = len(text)
    while i < n:
        j = text.find(src, i)
        if j < 0:
            out.append(text[i:])
            break
        out.append(text[i:j])
        after = text[j + len(src) :]
        before = text[:j]
        if any(after.startswith(tail) for tail in skip_tails):
            out.append(src)
            i = j + len(src)
            continue
        if any(before.endswith(head) for head in skip_heads):
            out.append(src)
            i = j + len(src)
            continue
        if require_context:
            honorific_ok = any(after.startswith(h) for h in _HONORIFICS)
            follow_ok = any(after.startswith(p) for p in _NAME_FOLLOW_OK)
            # Vocative stuck to next word: マイ大丈夫 / マイ好き
            kanji_follow = bool(after) and "\u4e00" <= after[0] <= "\u9fff"
            prefix_ok = any(before.endswith(p) for p in _NAME_PREFIX_OK)
            prev = before[-1] if before else ""
            # End-of-cue / before punctuation only if not glued to prior kana/kanji
            # (blocks トラマイ→トラ舞 while allowing bare 「マイ」 / 「、マイ」)
            eol_ok = (not after.strip()) and (not prev or not _is_cjk_letter(prev))
            whole = (not before.strip()) and (
                not after.strip() or after.lstrip()[:1] in "。.!！?？、,"
            )
            if not (
                honorific_ok
                or follow_ok
                or kanji_follow
                or prefix_ok
                or whole
                or eol_ok
            ):
                out.append(src)
                i = j + len(src)
                continue
        out.append(replacement)
        i = j + len(src)
    return "".join(out)


def _replace_term(text: str, src: str, replacement: str, *, name_safe: bool = False) -> str:
    """
    Replace glossary source with placeholder/target.

    Latin terms use whole-word boundaries (case-insensitive).
    CJK / mixed phrases use literal substring (longest-first already ordered).
    When ``name_safe`` and src looks like a short person name, use contextual
    replace so マイク / マイペース are not corrupted by マイ→舞.
    """
    if not src:
        return text
    if _is_latin_term(src):
        pattern = re.compile(
            rf"(?<![A-Za-z0-9_]){re.escape(src)}(?![A-Za-z0-9_])",
            re.IGNORECASE,
        )
        return pattern.sub(replacement, text)
    if src not in text:
        return text
    if name_safe and _looks_like_ja_person_token(src) and len(src) <= 4:
        return _replace_cjk_name_safe(text, src, replacement)
    return text.replace(src, replacement)


def protect_text(text: str, glossary: list[tuple[str, str]]) -> tuple[str, list[tuple[str, str]]]:
    """Replace glossary sources with placeholders; return (text, [(token, tgt), ...])."""
    raw = str(text or "")
    if not raw or not glossary:
        return raw, []
    mapping: list[tuple[str, str]] = []
    out = raw
    for i, (src, tgt) in enumerate(glossary):
        tok = _token(i)
        before = out
        out = _replace_term(out, src, tok)
        if out != before:
            mapping.append((tok, tgt))
    return out, mapping


def restore_text(text: str, mapping: list[tuple[str, str]]) -> str:
    out = str(text or "")
    if not mapping:
        return out
    for tok, tgt in mapping:
        if tok in out:
            out = out.replace(tok, tgt)
            continue
        # Mild MT mangling: underscores → spaces or dropped
        variants = {tok, tok.replace("_", " "), tok.replace("_", "")}
        replaced = False
        for variant in variants:
            if variant and variant in out:
                out = out.replace(variant, tgt)
                replaced = True
                break
        if not replaced and tgt and tgt not in out:
            # Avoid ``是。 汤米``-style append when Opus ate the placeholder and
            # left only a copula stub — leave a clean name for post-glossary polish.
            stub = out.strip()
            if stub in {"", "。", ".", "是", "是。", "是的", "是的。", "的", "的。"}:
                out = tgt
            elif re.fullmatch(r"[是的][。.\s]*", stub):
                out = tgt
            else:
                out = f"{out.rstrip()} {tgt}".strip()
    return out


def apply_glossary_to_cues(
    cues: list[dict[str, Any]],
    glossary: Any,
) -> tuple[list[dict[str, Any]], list[list[tuple[str, str]]]]:
    """
    Protect glossary terms in cue texts before MT.
    Returns (protected_cues, per_cue_mappings) for restore_glossary_on_cues.
    """
    asr_entries, mt_entries = split_glossary(glossary)
    if asr_entries or mt_entries:
        entries = mt_entries
    else:
        entries = normalize_glossary(glossary)
    if not entries:
        return list(cues or []), [[] for _ in (cues or [])]
    protected: list[dict[str, Any]] = []
    mappings: list[list[tuple[str, str]]] = []
    for cue in cues or []:
        text, mapping = protect_text(str(cue.get("text") or ""), entries)
        protected.append({**cue, "text": text})
        mappings.append(mapping)
    return protected, mappings


def apply_asr_glossary_to_cues(
    cues: list[dict[str, Any]] | None,
    glossary: Any,
    *,
    asr_only: bool = False,
    name_safe: bool = True,
) -> tuple[list[dict[str, Any]], int]:
    """
    Post-ASR source correction: replace misheard forms with correct terms.

    Accepts ``asrGlossary`` shapes and ``glossary`` entries tagged
    ``stage="asr"`` / ``wrong``+``correct``.

    When ``asr_only=True`` (dedicated asrGlossary field), untagged pairs are
    treated as ASR corrections. Otherwise only stage=asr / wrong+correct apply.

    With ``name_safe=True`` (default), short JA name tokens are expanded to
    honorific/phrase forms and replaced with loanword guards (マイ≠マイク).

    Returns (cues, replacement_hit_count).
    """
    asr_entries, _mt = split_glossary(glossary)
    if asr_only and not asr_entries:
        asr_entries = normalize_glossary(glossary)
    if not asr_entries:
        return list(cues or []), 0
    if name_safe:
        asr_entries = expand_asr_name_entries(asr_entries)
    out: list[dict[str, Any]] = []
    hits = 0
    for cue in cues or []:
        if not isinstance(cue, dict):
            continue
        text = str(cue.get("text") or "")
        new_text = text
        for src, tgt in asr_entries:
            before = new_text
            new_text = _replace_term(new_text, src, tgt, name_safe=name_safe)
            if new_text != before:
                hits += 1
        out.append({**cue, "text": new_text} if new_text != text else dict(cue))
    return out, hits


def restore_glossary_on_cues(
    cues: list[dict[str, Any]],
    mappings: list[list[tuple[str, str]]],
) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for i, cue in enumerate(cues or []):
        mapping = mappings[i] if i < len(mappings) else []
        text = restore_text(str(cue.get("text") or ""), mapping)
        out.append({**cue, "text": text})
    return out


def enforce_glossary_on_cues(
    source_cues: list[dict[str, Any]] | None,
    zh_cues: list[dict[str, Any]] | None,
    glossary: Any,
) -> list[dict[str, Any]]:
    """
    Post-MT hard constraint: if source cue contained a glossary src, force tgt
    into the translated cue (replace leftover src, append if still missing).
    """
    asr_entries, mt_entries = split_glossary(glossary)
    if asr_entries or mt_entries:
        entries = mt_entries
    else:
        entries = normalize_glossary(glossary)
    src_list = list(source_cues or [])
    zh_list = list(zh_cues or [])
    if not entries:
        return zh_list
    out: list[dict[str, Any]] = []
    n = max(len(src_list), len(zh_list))
    for i in range(n):
        src_cue = src_list[i] if i < len(src_list) else {}
        zh_cue = (
            zh_list[i]
            if i < len(zh_list)
            else {"start": src_cue.get("start"), "end": src_cue.get("end"), "text": ""}
        )
        src_text = str(src_cue.get("text") or "")
        zh_text = str(zh_cue.get("text") or "")
        for src, tgt in entries:
            hit = False
            if _is_latin_term(src):
                hit = bool(
                    re.search(
                        rf"(?<![A-Za-z0-9_]){re.escape(src)}(?![A-Za-z0-9_])",
                        src_text,
                        re.IGNORECASE,
                    )
                )
            else:
                hit = src in src_text
            if not hit:
                continue
            zh_text = _replace_term(zh_text, src, tgt)
            if tgt and tgt not in zh_text:
                zh_text = f"{zh_text.rstrip()} {tgt}".strip() if zh_text.strip() else tgt
        out.append({**zh_cue, "text": zh_text})
    return out
